package item

type Item struct {
	Sku string
	Name string
	City string
	Note string
	Code string
	Kind string
	Zone string
	Rank string
}

func GetSku(item Item) string {
	return item.Sku
}

func GetName(item Item) string {
	return item.Name
}

func GetCity(item Item) string {
	return item.City
}

func GetNote(item Item) string {
	return item.Note
}

func GetCode(item Item) string {
	return item.Code
}

func GetKind(item Item) string {
	return item.Kind
}

func GetZone(item Item) string {
	return item.Zone
}

func GetRank(item Item) string {
	return item.Rank
}

